const lockOrganization = `-- name: LockOrganization :one
SELECT id
FROM organizations
WHERE id = $1
FOR UPDATE
`

// Serializes owner-invariant flows (last-owner check + member delete) across
// concurrent member removals in the same organization.
func (q *Queries) LockOrganization(ctx context.Context, id int64) (int64, error) {
	row := q.db.QueryRow(ctx, lockOrganization, id)
	err := row.Scan(&id)
	return id, err
}

