const updateOrganization = `-- name: UpdateOrganization :one
UPDATE organizations
SET name = $1,
    lower_name = $2,
    description = $3,
    visibility = $4,
    website = $5,
    location = $6,
    factory_owner_id = CASE WHEN $7::boolean THEN $8::bigint ELSE factory_owner_id END,
    updated_at = NOW()
WHERE id = $9
RETURNING id, name, lower_name, description, visibility, website, location, created_at, updated_at, factory_owner_id
`

type UpdateOrganizationParams struct {
	Name            string      `json:"name"`
	LowerName       string      `json:"lower_name"`
	Description     string      `json:"description"`
	Visibility      string      `json:"visibility"`
	Website         string      `json:"website"`
	Location        string      `json:"location"`
	SetFactoryOwner bool        `json:"set_factory_owner"`
	FactoryOwnerID  pgtype.Int8 `json:"factory_owner_id"`
	ID              int64       `json:"id"`
}

func (q *Queries) UpdateOrganization(ctx context.Context, arg UpdateOrganizationParams) (Organization, error) {
	row := q.db.QueryRow(ctx, updateOrganization,
		arg.Name,
		arg.LowerName,
		arg.Description,
		arg.Visibility,
		arg.Website,
		arg.Location,
		arg.SetFactoryOwner,
		arg.FactoryOwnerID,
		arg.ID,
	)
	var i Organization
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.LowerName,
		&i.Description,
		&i.Visibility,
		&i.Website,
		&i.Location,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.FactoryOwnerID,
	)
	return i, err
}

